import clsx from 'clsx'
import { KTIcon, toAbsoluteUrl, getNotificationUI } from '../../../helpers'
import { HeaderNotificationsMenu, HeaderUserMenu, ThemeModeSwitcher, Search, LanguageSwitcher } from '../../../partials'
import { useLayout } from '../../core'
import { useEffect, useState } from 'react'
import { Link } from 'react-router-dom'

const itemClass = 'ms-1 ms-md-4'
const btnClass =
  'btn btn-icon btn-custom btn-icon-muted btn-active-light btn-active-color-primary w-35px h-35px'
const userAvatarClass = 'symbol-35px'
const btnIconClass = 'fs-2'

const playPopSound = () => {
  const audio = new Audio(toAbsoluteUrl('/media/pop-402324.mp3'));
  audio.play().catch(e => {
    if (e.name !== 'NotAllowedError') {
      console.error("Audio play failed", e);
    }
  });
};

type Notification = {
  title: string;
  description: string;
  time: string;
  icon: string;
  color: string;
};

const Navbar = () => {
  const { config } = useLayout()
  const [hasNotifications, setHasNotifications] = useState(false)
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [pendingCount, setPendingCount] = useState<number>(0)

  // WebSocket Listener
  useEffect(() => {
    return () => {
    };
  }, []);

  useEffect(() => {
    let lastCount = 0;

    const fetchNotifications = async () => {
      try {
        const token = localStorage.getItem('token') || localStorage.getItem('auth_token');
        const apiUrl = process.env.REACT_APP_API_URL || 'http://localhost:8000/api';

        const response = await fetch(`${apiUrl}/notifications`, {
          headers: {
            'Authorization': `Bearer ${token}`,
            'Accept': 'application/json'
          }
        });

        if (response.ok) {
          const data = await response.json();
          if (data.notifications && data.notifications.length > 0) {
            const mapped = data.notifications.map((n: any) => {
              const title = n.data.title || (n.data.type === 'order_status_update' ? 'Order Update' : (n.data.client_name ? `New Order: ${n.data.client_name}` : 'Notification'));
              const ui = getNotificationUI(n.data.type, title);
              return {
                title: title,
                description: n.data.message || (n.data.order_id ? `Order #${n.data.order_id} is Pending` : ''),
                time: new Date(n.created_at).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
                icon: ui.icon,
                color: ui.color,
                read: !!n.read_at
              };
            });

            setNotifications(mapped);
            setHasNotifications(true);

            // Play sound if we have new unread notifications compared to last polling
            if (data.notifications.length > lastCount) {
              playPopSound();
            }
            lastCount = data.notifications.length;
          } else {
            setNotifications([]);
            setHasNotifications(false);
            lastCount = 0;
          }
        }
      } catch (error) {
        console.error("Failed to fetch notifications", error);
      }
    };

    const fetchPendingCount = async () => {
      try {
        const token = localStorage.getItem('token') || localStorage.getItem('auth_token');
        const apiUrl = process.env.REACT_APP_API_URL || 'http://localhost:8000/api';
        const response = await fetch(`${apiUrl}/magento/orders/pending-count`, {
          headers: {
            'Authorization': `Bearer ${token}`,
            'Accept': 'application/json'
          }
        });
        if (response.ok) {
          const data = await response.json();
          setPendingCount(data.count || 0);
        }
      } catch (error) {
        console.error("Failed to fetch pending count", error);
      }
    };

    fetchNotifications();
    fetchPendingCount();
    const interval = setInterval(() => {
      fetchPendingCount();
    }, 100000); // Poll every 10 seconds
    return () => clearInterval(interval);
  }, []);

  return (
    <div className='app-navbar flex-shrink-0 d-flex align-items-center'>
      <Search />

      <div className={clsx('app-navbar-item', itemClass)}>
        <Link
          to='/orders-pending'
          className={clsx('position-relative', btnClass)}
          title='Orders To Confirm'
          style={{ textDecoration: 'none' }}
        >
          <KTIcon iconName='clipboard' className={btnIconClass} />
          {pendingCount > 0 && (
            <span className='badge badge-circle badge-danger position-absolute translate-middle top-0 start-50 w-16px h-16px fs-9 d-flex justify-content-center align-items-center' style={{ boxShadow: '0 0 10px rgba(241, 65, 108, 0.4)' }}>
              {pendingCount}
            </span>
          )}
        </Link>
      </div>

      <div className={clsx('app-navbar-item', itemClass)}>
        <div
          className={clsx('position-relative', btnClass)}
          data-kt-menu-trigger="click"
          data-kt-menu-attach="parent"
          data-kt-menu-placement="bottom-end"
        >
          <KTIcon iconName='notification-on' className={btnIconClass} />
          {hasNotifications && (
            <span className='bullet bullet-dot bg-danger h-6px w-6px position-absolute translate-middle top-0 start-50 animation-blink' />
          )}
        </div>
        <HeaderNotificationsMenu notifications={notifications} />
      </div>

      <div className={clsx('app-navbar-item', itemClass)}>
        <ThemeModeSwitcher toggleBtnClass={clsx('btn-active-light-primary btn-custom')} />
      </div>

      <LanguageSwitcher />

      <div className={clsx('app-navbar-item', itemClass)}>
        <div
          className={clsx('cursor-pointer symbol', userAvatarClass)}
          data-kt-menu-trigger="{default: 'click'}"
          data-kt-menu-attach='parent'
          data-kt-menu-placement='bottom-end'
        >
          <img src={toAbsoluteUrl('/media/avatars/blank.png')} alt='' />
        </div>
        <HeaderUserMenu />
      </div>

      {config.app?.header?.default?.menu?.display && (
        <div className='app-navbar-item d-lg-none ms-2 me-n3' title='Show header menu'>
          <div
            className='btn btn-icon btn-active-color-primary w-35px h-35px'
            id='kt_app_header_menu_toggle'
          >
            <KTIcon iconName='text-align-left' className={btnIconClass} />
          </div>
        </div>
      )}
    </div>
  )
}

export { Navbar }
