/* eslint-disable react/jsx-no-target-blank */
import React from 'react'
import { useIntl } from 'react-intl'
import { KTIcon } from '../../../../helpers'
import { SidebarMenuItemWithSub } from './SidebarMenuItemWithSub'
import { SidebarMenuItem } from './SidebarMenuItem'
import { useAuth } from '../../../../../app/modules/auth'

const SidebarMenuMain = () => {
  const intl = useIntl()
  const { currentUser } = useAuth()
  const access = currentUser?.sidebar_access || []
  const isAdmin = currentUser?.roles?.includes('admin') || currentUser?.roles?.includes('super admin')

  const hasAccess = (module: string) => {
    if (isAdmin) return true
    return access.includes(module)
  }

  return (
    <>
      {hasAccess('dashboard') && (
        <SidebarMenuItem
          to='/dashboard'
          icon='element-11'
          title={intl.formatMessage({ id: 'MENU.DASHBOARD' })}
          fontIcon='bi-app-indicator'
        />
      )}

      {(hasAccess('orders') || hasAccess('to-confirm') || hasAccess('confirmed-orders') || hasAccess('products') || hasAccess('vendors') || hasAccess('intigo') || hasAccess('users')) && (
        <div className='menu-item'>
          <div className='menu-content pt-8 pb-2'>
            <span className='menu-section text-muted text-uppercase fs-8 ls-1'>
              {intl.formatMessage({id: 'MENU.APPS'})}
            </span>
          </div>
        </div>
      )}

      {(hasAccess('orders') || hasAccess('to-confirm') || hasAccess('confirmed-orders') || hasAccess('processing') || hasAccess('complete') || hasAccess('on-hold')) && (
        <SidebarMenuItemWithSub
          to='/orders'
          title={intl.formatMessage({id: 'MENU.ORDER_MANAGEMENT'})}
          fontIcon='bi-archive'
          icon='element-plus'
        >
          {hasAccess('orders') && (
            <SidebarMenuItem 
              to='/orders' 
              title={intl.formatMessage({id: 'MENU.ALL_ORDERS'})} 
              hasBullet={true} 
              exact={true} 
            />
          )}
          {hasAccess('to-confirm') && (
            <SidebarMenuItem 
              to='/orders-availability' 
              title={intl.formatMessage({id: 'MENU.AVAILABILITY'})} 
              hasBullet={true} 
            />
          )}
          {hasAccess('to-confirm') && (
            <SidebarMenuItem 
              to='/orders-unavailable' 
              title={intl.formatMessage({id: 'MENU.NON_DISPONIBLE'})} 
              hasBullet={true}
              badge="NEW"
              badgeColor="danger"
            />
          )}
          {hasAccess('to-confirm') && (
            <SidebarMenuItem 
              to='/orders-pending' 
              title={intl.formatMessage({id: 'MENU.TO_CONFIRM'})} 
              hasBullet={true} 
            />
          )}
          {hasAccess('confirmed-orders') && (
            <SidebarMenuItem 
              to='/orders-confirmed' 
              title={intl.formatMessage({id: 'MENU.CONFIRMED'})} 
              hasBullet={true} 
            />
          )}
          {hasAccess('tracking') && (
            <SidebarMenuItem 
              to='/orders-tracking' 
              title={intl.formatMessage({id: 'MENU.TRACKING'})} 
              hasBullet={true} 
            />
          )}
        </SidebarMenuItemWithSub>
      )}
      {hasAccess('products') && (
        <SidebarMenuItem
          to='/products'
          icon='package'
          title={intl.formatMessage({id: 'MENU.PRODUCTS'})}
          fontIcon='bi-box'
        />
      )}
      {hasAccess('vendors') && (
        <SidebarMenuItem
          to='/vendors'
          icon='profile-circle'
          title={intl.formatMessage({id: 'MENU.VENDORS'})}
          fontIcon='bi-person'
        />
      )}
      {hasAccess('intigo') && (
        <SidebarMenuItem
          to='/intigo'
          icon='delivery-2'
          title={intl.formatMessage({id: 'MENU.INTIGO'})}
          fontIcon='bi-truck'
        />
      )}
      {hasAccess('users') && (
        <SidebarMenuItem
          to='/users'
          icon='user'
          title={intl.formatMessage({id: 'MENU.USERS'})}
          fontIcon='bi-people'
        />
      )}
      {(isAdmin || hasAccess('sidebar-config')) && (
        <SidebarMenuItem
          to='/sidebar-config'
          icon='setting-2'
          title={intl.formatMessage({id: 'MENU.SIDEBAR_CONFIG'})}
          fontIcon='bi-gear'
        />
      )}

      {(hasAccess('history') || hasAccess('bordereau')) && (
        <div className='menu-item'>
          <div className='menu-content pt-8 pb-2'>
            <span className='menu-section text-muted text-uppercase fs-8 ls-1'>
              {intl.formatMessage({id: 'MENU.TOOLS'})}
            </span>
          </div>
        </div>
      )}

      {hasAccess('history') && (
        <SidebarMenuItem
          to='/history'
          icon='calendar-8'
          title={intl.formatMessage({id: 'MENU.HISTORY'})}
          fontIcon='bi-clock-history'
        />
      )}
      {hasAccess('bordereau') && (
        <SidebarMenuItem
          to='/bordereau'
          icon='document'
          title={intl.formatMessage({id: 'MENU.BORDEREAUX'})}
          fontIcon='bi-file-text'
        />
      )}
    </>
  )
}

export { SidebarMenuMain }
