import { lazy, FC, Suspense } from 'react'
import { Route, Routes, Navigate } from 'react-router-dom'
import { MasterLayout } from '../../_metronic/layout/MasterLayout'
import TopBarProgress from 'react-topbar-progress-indicator'
import { DashboardWrapper } from '../pages/dashboard/DashboardWrapper'
import { DashboardUnderConstruction } from '../pages/dashboard/DashboardUnderConstruction'
import { getCSSVariableValue } from '../../_metronic/assets/ts/_utils'
import { WithChildren } from '../../_metronic/helpers'
import BuilderPageWrapper from '../pages/layout-builder/BuilderPageWrapper'

const PrivateRoutes = () => {
  const MagentoOrdersPage = lazy(() => import('../modules/apps/magento-orders/MagentoOrdersPage'))
  const MagentoOrdersPendingPage = lazy(() => import('../modules/apps/magento-orders/MagentoOrdersPendingPage'))
  const ProductsPage = lazy(() => import('../pages/products/ProductsPage'))
  const HistoryPage = lazy(() => import('../pages/history/HistoryPage'))
  const BordereauPage = lazy(() => import('../pages/bordereau/BordereauPage'))
  const GenerateBordereaux = lazy(() => import('../pages/bordereau/GenerateBordereaux'))
  const MagentoOrdersConfirmedPage = lazy(() => import('../modules/apps/magento-orders/MagentoOrdersConfirmedPage'))
  const MagentoOrdersTrackingPage = lazy(() => import('../modules/apps/magento-orders/MagentoOrdersTrackingPage'))
  const MagentoOrdersAvailabilityPage = lazy(() => import('../modules/apps/magento-orders/MagentoOrdersAvailabilityPage'))
  const MagentoOrdersUnavailablePage = lazy(() => import('../modules/apps/magento-orders/MagentoOrdersUnavailablePage'))
  const VendorsPage = lazy(() => import('../pages/vendors/VendorsPage'))
  const IntigoPage = lazy(() => import('../modules/apps/intigo/IntigoPage'))
  const SidebarConfigPage = lazy(() => import('../modules/apps/sidebar-config/SidebarConfigPage'))
  const UsersPage = lazy(() => import('../modules/apps/user-management/UsersPage'))

  return (
    <Routes>
      <Route element={<MasterLayout />}>
        {/* Redirect to Dashboard after success login/registartion */}
        <Route path='auth/*' element={<Navigate to='/dashboard' />} />
        {/* Pages */}
        <Route path='dashboard' element={<DashboardUnderConstruction />} />
        <Route path='dashboard-dev' element={<DashboardWrapper />} />
        <Route path='builder' element={<BuilderPageWrapper />} />
        <Route
          path='intigo'
          element={
            <SuspensedView>
              <IntigoPage />
            </SuspensedView>
          }
        />

        <Route
          path='products'
          element={
            <SuspensedView>
              <ProductsPage />
            </SuspensedView>
          }
        />
        <Route
          path='history'
          element={
            <SuspensedView>
              <HistoryPage />
            </SuspensedView>
          }
        />
        <Route
          path='bordereau'
          element={
            <SuspensedView>
              <BordereauPage />
            </SuspensedView>
          }
        />
        <Route
          path='generate-bordereaux'
          element={
            <SuspensedView>
              <GenerateBordereaux />
            </SuspensedView>
          }
        />
        <Route
          path='orders/*'
          element={
            <Suspense fallback={<TopBarProgress />}>
              <MagentoOrdersPage />
            </Suspense>
          }
        />
        <Route
          path='orders-pending'
          element={
            <Suspense fallback={<TopBarProgress />}>
              <MagentoOrdersPendingPage />
            </Suspense>
          }
        />
        <Route
          path='orders-confirmed'
          element={
            <Suspense fallback={<TopBarProgress />}>
              <MagentoOrdersConfirmedPage />
            </Suspense>
          }
        />
        <Route
          path='orders-tracking'
          element={
            <Suspense fallback={<TopBarProgress />}>
              <MagentoOrdersTrackingPage />
            </Suspense>
          }
        />
        <Route
          path='orders-availability'
          element={
            <Suspense fallback={<TopBarProgress />}>
              <MagentoOrdersAvailabilityPage />
            </Suspense>
          }
        />
        <Route
          path='orders-unavailable'
          element={
            <Suspense fallback={<TopBarProgress />}>
              <MagentoOrdersUnavailablePage />
            </Suspense>
          }
        />
        <Route
          path='vendors'
          element={
            <SuspensedView>
              <VendorsPage />
            </SuspensedView>
          }
        />
        <Route
          path='users/*'
          element={
            <Suspense fallback={<TopBarProgress />}>
              <UsersPage />
            </Suspense>
          }
        />
        <Route
          path='sidebar-config'
          element={
            <Suspense fallback={<TopBarProgress />}>
              <SidebarConfigPage />
            </Suspense>
          }
        />
        {/* Page Not Found */}
        <Route path='*' element={<Navigate to='/error/404' />} />
      </Route>
    </Routes>
  )
}

const SuspensedView: FC<WithChildren> = ({ children }) => {
  const baseColor = getCSSVariableValue('--bs-primary')
  TopBarProgress.config({
    barColors: {
      '0': baseColor,
    },
    barThickness: 1,
    shadowBlur: 5,
  })
  return <Suspense fallback={<TopBarProgress />}>{children}</Suspense>
}

export { PrivateRoutes }
