import { useState } from 'react'
import * as Yup from 'yup'
import { Link } from 'react-router-dom'
import clsx from 'clsx'
import { useFormik } from 'formik'
import { login, sellerLogin } from '../core/_requests'
import { useAuth } from '../core/Auth'
import { useNavigate } from 'react-router-dom'
import { KTIcon } from '../../../../_metronic/helpers'

const loginSchema = Yup.object().shape({
    username: Yup.string()
        .min(3, 'Minimum 3 symbols')
        .max(50, 'Maximum 50 symbols')
        .required('Username is required'),
    password: Yup.string()
        .min(3, 'Minimum 3 symbols')
        .max(50, 'Maximum 50 symbols')
        .required('Password is required'),
})

const initialValues = {
    username: 'ayoubmekni',
    password: 'Arkan@123',
}

export function MagentoLogin() {
    const [loading, setLoading] = useState(false)
    const { saveAuth, setCurrentUser } = useAuth()
    const navigate = useNavigate()

    const formik = useFormik({
        initialValues,
        validationSchema: loginSchema,
        onSubmit: async (values, { setStatus, setSubmitting }) => {
            setLoading(true)
            console.log('Attempting login for:', values.username)
            try {
                // Heuristic: If username contains '@', assume seller (email). otherwise admin.
                const isSeller = values.username.includes('@');

                if (isSeller) {
                    // Try Seller Login
                    const { data } = await sellerLogin(values.username, values.password)
                    console.log('Seller login response:', data)

                    if (data && data.success && (data.token || data.customer_token)) {
                        // Create auth object compatible with AuthModel
                        const auth = {
                            api_token: data.token || data.customer_token,
                            refreshToken: data.token || data.customer_token
                        }
                        saveAuth(auth)

                        const user = {
                            id: 12,
                            username: values.username,
                            password: 'hidden',
                            email: values.username,
                            first_name: 'Seller',
                            last_name: 'User',
                            pic: './media/avatars/300-1.jpg',
                            roles: ['seller'],
                            sidebar_access: ['dashboard', 'orders', 'products', 'bordereau']
                        };
                        setCurrentUser(user)
                        console.log('Seller authenticated. Navigating to local dashboard...')
                        navigate('/dashboard')
                        return;
                    }
                }

                // Try Admin Login (Default or Fallback)
                console.log('Attempting Admin login...')
                const { data: auth } = await login(values.username, values.password)
                console.log('Admin login response:', auth)

                // The server might return 'token' instead of 'api_token', we check both.
                const authObject = auth as any;
                if (authObject && (authObject.api_token || authObject.token)) {
                    const authData = {
                        ...authObject,
                        api_token: authObject.api_token || authObject.token,
                        refreshToken: authObject.refreshToken || authObject.token
                    };
                    saveAuth(authData)
                    const user = {
                        id: 1,
                        username: values.username,
                        password: 'mock_password',
                        email: 'admin@arkan.com',
                        first_name: 'Admin',
                        last_name: 'User',
                        pic: './media/avatars/300-1.jpg',
                        roles: ['admin'],
                        sidebar_access: ['dashboard', 'orders', 'to-confirm', 'confirmed-orders', 'products', 'vendors', 'intigo', 'users', 'history', 'bordereau']
                    };
                    setCurrentUser(user)
                    console.log('Admin Auth saved. Navigating to dashboard...')
                    navigate('/dashboard')
                } else {
                    console.error('Login failed: Token missing in response')
                    setStatus('Login failed: Token not received from server')
                    setSubmitting(false)
                    setLoading(false)
                }
            } catch (error: any) {
                console.error('Login Error:', error)
                saveAuth(undefined)
                const errorMsg = error.response?.data?.message || 'Connection to server failed'
                setStatus(errorMsg)
                setSubmitting(false)
                setLoading(false)
            }
        },
    })

    return (
        <div className='d-flex flex-column flex-column-fluid bgi-size-cover bgi-position-center'>
            <div className='d-flex flex-center flex-column flex-column-fluid p-10 pb-lg-20'>
                <div className='w-lg-500px bg-body rounded shadow-sm p-10 p-lg-15 mx-auto card border-0'
                    style={{
                        backdropFilter: 'blur(10px)',
                        background: 'rgba(255, 255, 255, 0.8)',
                        boxShadow: '0 8px 32px 0 rgba(31, 38, 135, 0.37)'
                    }}>
                    <form
                        className='form w-100'
                        onSubmit={formik.handleSubmit}
                        noValidate
                        id='kt_login_signin_form'
                    >
                        <div className='text-center mb-10'>
                            <h1 className='text-dark mb-3' style={{ fontWeight: 800, fontSize: '2.5rem', letterSpacing: '-1px' }}>
                                Arkan <span className='text-primary'>Shipping</span>
                            </h1>
                            <div className='text-gray-400 fw-bold fs-4'>Magento Integration Hub</div>
                        </div>

                        {formik.status && (
                            <div className='mb-lg-15 alert alert-danger d-flex align-items-center p-5'>
                                <KTIcon iconName='shield-cross' className='fs-2hx text-danger me-4' />
                                <div className='d-flex flex-column'>
                                    <h4 className='mb-1 text-danger'>Authentication Error</h4>
                                    <span>{formik.status}</span>
                                </div>
                            </div>
                        )}

                        <div className='fv-row mb-10'>
                            <label className='form-label fs-6 fw-bolder text-dark'>Magento Username</label>
                            <div className='position-relative'>
                                <input
                                    placeholder='Enter username'
                                    {...formik.getFieldProps('username')}
                                    className={clsx(
                                        'form-control form-control-lg form-control-solid',
                                        { 'is-invalid': formik.touched.username && formik.errors.username },
                                        { 'is-valid': formik.touched.username && !formik.errors.username }
                                    )}
                                    type='text'
                                    name='username'
                                    autoComplete='off'
                                />
                            </div>
                            {formik.touched.username && formik.errors.username && (
                                <div className='fv-plugins-message-container'>
                                    <span role='alert' className='text-danger'>{formik.errors.username}</span>
                                </div>
                            )}
                        </div>

                        <div className='fv-row mb-10'>
                            <div className='d-flex flex-stack mb-2'>
                                <label className='form-label fw-bolder text-dark fs-6 mb-0'>Password</label>
                            </div>
                            <input
                                type='password'
                                placeholder='Enter password'
                                autoComplete='off'
                                {...formik.getFieldProps('password')}
                                className={clsx(
                                    'form-control form-control-lg form-control-solid',
                                    { 'is-invalid': formik.touched.password && formik.errors.password },
                                    { 'is-valid': formik.touched.password && !formik.errors.password }
                                )}
                            />
                            {formik.touched.password && formik.errors.password && (
                                <div className='fv-plugins-message-container'>
                                    <div className='fv-help-block'>
                                        <span role='alert' className='text-danger'>{formik.errors.password}</span>
                                    </div>
                                </div>
                            )}
                        </div>

                        <div className='text-center'>
                            <button
                                type='submit'
                                id='kt_sign_in_submit'
                                className='btn btn-lg btn-primary w-100 mb-5 shadow-sm'
                                style={{ height: '55px', fontSize: '1.1rem', fontWeight: 700 }}
                                disabled={formik.isSubmitting || !formik.isValid}
                            >
                                {!loading && <span className='indicator-label'>Authenticate Account</span>}
                                {loading && (
                                    <span className='indicator-progress' style={{ display: 'block' }}>
                                        Authenticating...
                                        <span className='spinner-border spinner-border-sm align-middle ms-2'></span>
                                    </span>
                                )}
                            </button>

                            <div className='separator separator-content my-10'>
                                <span className='w-125px text-gray-500 fw-bold fs-7'>Demo Mode</span>
                            </div>

                            <button
                                type='button'
                                className='btn btn-lg btn-light-success w-100 mb-5 shadow-sm border border-success border-dashed'
                                style={{ height: '55px', fontSize: '1rem', fontWeight: 600 }}
                                onClick={() => {
                                    formik.setFieldValue('username', 'ayoubmekni')
                                    formik.setFieldValue('password', 'Arkan@123')
                                    setTimeout(() => formik.handleSubmit(), 100)
                                }}
                            >
                                <KTIcon iconName='rocket' className='fs-2 me-2 text-success' />
                                Quick Login (Admin Demo)
                            </button>
                        </div>
                    </form>
                </div>
            </div>
        </div>
    )
}
